```handlebars
{{#if profile.shoppingCartItems}}
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">
  {{#each profile.shoppingCartItems}}
    {{#lt @index 3}}
    <tr>
      <td width="120" valign="top" style="padding-bottom:16px;">
        <a href="{{url}}"><img src="{{imageUrl}}" alt="{{name}}" width="120" style="display:block;"></a>
      </td>
      <td valign="top" style="padding-left:16px; padding-bottom:16px;">
        <a href="{{url}}" style="font-weight:bold; text-decoration:none; color:#000;">{{name}}</a><br>
