      </td>
    </tr>
    {{/lt}}
  {{/each}}
  {{#ifGt profile.shoppingCartItems.size 3}}
  <tr>
    <td colspan="2" style="padding-top:8px; font-style:italic; color:#666;">
      and more in your cart
    </td>
  </tr>
  {{/ifGt}}
</table>
{{/if}}
```

